//! Shared value types: identifiers, status, metadata, retry policy, and the
//! data structures that cross the `TaskQueue` boundary.

use std::fmt;
use std::time::Duration;

use rand::RngExt;
use serde::{Deserialize, Serialize};
use time::OffsetDateTime;
use uuid::Uuid;

use crate::error::{QueueError, QueueResult};

// ---------------------------------------------------------------- identifiers

/// Unique task identifier, generated by the backend at enqueue time and
/// stable across retries.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(transparent)]
pub struct TaskId(Uuid);

impl TaskId {
    pub fn generate() -> Self {
        Self(Uuid::new_v4())
    }

    pub const fn from_uuid(uuid: Uuid) -> Self {
        Self(uuid)
    }

    pub const fn as_uuid(self) -> Uuid {
        self.0
    }
}

impl fmt::Display for TaskId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

impl From<Uuid> for TaskId {
    fn from(value: Uuid) -> Self {
        Self(value)
    }
}

/// Identifies the worker that holds a claim. Used for lease-ownership checks:
/// only the worker recorded in `claimed_by` may ack/fail/release a task.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct WorkerId(String);

impl WorkerId {
    pub fn new(value: impl Into<String>) -> Self {
        Self(value.into())
    }

    pub fn generate() -> Self {
        Self(format!("worker-{}", Uuid::new_v4()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for WorkerId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

// -------------------------------------------------------------------- status

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TaskStatus {
    /// Eligible for claiming (possibly not before `available_at`).
    Pending,
    /// Claimed by a worker under an active lease.
    Running,
    /// Acknowledged as successfully completed.
    Completed,
    /// Dead-lettered: retry budget exhausted or a non-retryable failure.
    Failed,
    /// Cancelled before execution.
    Cancelled,
}
#[allow(unused)]
impl TaskStatus {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Pending => "pending",
            Self::Running => "running",
            Self::Completed => "completed",
            Self::Failed => "failed",
            Self::Cancelled => "cancelled",
        }
    }

    /// Parse a status as stored by a backend. Kept explicit (rather than a
    /// derive) so backends control their on-disk representation.
    pub(crate) fn from_db(value: &str) -> QueueResult<Self> {
        match value {
            "pending" => Ok(Self::Pending),
            "running" => Ok(Self::Running),
            "completed" => Ok(Self::Completed),
            "failed" => Ok(Self::Failed),
            "cancelled" => Ok(Self::Cancelled),
            other => Err(QueueError::Backend(
                format!("unknown task status `{other}`").into(),
            )),
        }
    }
}

impl fmt::Display for TaskStatus {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

// -------------------------------------------------------------- retry policy

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum BackoffStrategy {
    Fixed {
        delay: Duration,
    },
    Exponential {
        base: Duration,
        factor: f64,
        max: Duration,
        jitter: f64,
    },
}

impl Default for BackoffStrategy {
    fn default() -> Self {
        Self::Exponential {
            base: Duration::from_secs(1),
            factor: 2.0,
            max: Duration::from_secs(60),
            jitter: 0.1,
        }
    }
}

/// Per-task retry configuration, persisted alongside the payload so any
/// backend can compute backoff without knowing the strategy.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RetryPolicy {
    /// Total number of *claims* (execution attempts) allowed.
    pub max_attempts: u32,
    pub backoff: BackoffStrategy,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        Self {
            max_attempts: 3,
            backoff: BackoffStrategy::default(),
        }
    }
}

impl RetryPolicy {
    /// Delay before the retry that follows failed attempt `failed_attempt`
    /// (1-based). Jitter applies only to `Exponential`.
    pub fn delay_after_attempt(&self, failed_attempt: u32) -> Duration {
        debug_assert!(failed_attempt >= 1);
        match &self.backoff {
            BackoffStrategy::Fixed { delay } => *delay,
            BackoffStrategy::Exponential {
                base,
                factor,
                max,
                jitter,
            } => {
                let exponent = failed_attempt.saturating_sub(1).min(62);
                let raw = base.as_secs_f64() * factor.powi(exponent as i32);
                let capped = raw.min(max.as_secs_f64());
                let jitter_factor = if *jitter > 0.0 {
                    1.0 + rand::rng().random_range(-*jitter..=*jitter)
                } else {
                    1.0
                };
                Duration::from_secs_f64((capped * jitter_factor).max(0.0))
            }
        }
    }
}

// ------------------------------------------------------------------ metadata

/// Queue-facing metadata for a task.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TaskMetadata {
    /// Higher priority is claimed first (best effort, not a strict ordering).
    pub priority: i16,
    pub retry_policy: RetryPolicy,
    /// Earliest claim time; `None` means immediately eligible.
    pub run_at: Option<OffsetDateTime>,
    /// Enqueue-time idempotency key: at most one task per key may be pending
    /// or running. Does not deduplicate terminal (completed/failed) tasks.
    pub dedup_key: Option<String>,
}
#[allow(clippy::derivable_impls)]
impl Default for TaskMetadata {
    fn default() -> Self {
        Self {
            priority: 0,
            retry_policy: RetryPolicy::default(),
            run_at: None,
            dedup_key: None,
        }
    }
}

// ------------------------------------------------------- queue data contract

/// The backend-agnostic representation accepted by `TaskQueue::enqueue`.
/// Constructed via `Task::into_new_task*`; backends never see concrete task types.
#[derive(Debug, Clone)]
pub struct NewTask {
    pub task_type: String,
    pub payload_version: u16,
    pub payload: Vec<u8>,
    pub priority: i16,
    pub retry_policy: RetryPolicy,
    pub run_at: OffsetDateTime,
    pub dedup_key: Option<String>,
}

/// Full persisted state of a task, as returned by `enqueue` and `get`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TaskRecord {
    pub id: TaskId,
    pub task_type: String,
    pub payload_version: u16,
    pub payload: Vec<u8>,
    pub status: TaskStatus,
    pub priority: i16,
    /// Number of claims so far (includes the current one if `Running`).
    pub attempts: u32,
    pub max_attempts: u32,
    pub retry_policy: RetryPolicy,
    pub available_at: OffsetDateTime,
    pub created_at: OffsetDateTime,
    pub updated_at: OffsetDateTime,
    pub completed_at: Option<OffsetDateTime>,
    pub claimed_at: Option<OffsetDateTime>,
    pub claimed_by: Option<WorkerId>,
    pub lease_expires_at: Option<OffsetDateTime>,
    pub last_error: Option<String>,
    pub dedup_key: Option<String>,
}

/// A task claimed by a worker, carrying the lease needed to resolve it.
///
/// Not `Clone` on purpose: `ack`/`fail`/`release` consume it, making it a
/// single-use token — a claim cannot be resolved twice through the type system.
#[derive(Debug)]
pub struct ClaimedTask {
    pub record: TaskRecord,
    pub worker_id: WorkerId,
}

impl ClaimedTask {
    pub const fn id(&self) -> TaskId {
        self.record.id
    }

    /// 1-based attempt number of this execution.
    pub const fn attempt(&self) -> u32 {
        self.record.attempts
    }
}

/// Failure report passed to `TaskQueue::fail`.
#[derive(Debug, Clone)]
pub struct TaskFailure {
    /// Human-readable error, persisted in `last_error` for inspection.
    pub error: String,
    /// `false` dead-letters the task immediately, bypassing the retry policy.
    pub retryable: bool,
}

impl TaskFailure {
    pub fn transient(error: impl Into<String>) -> Self {
        Self {
            error: error.into(),
            retryable: true,
        }
    }

    pub fn permanent(error: impl Into<String>) -> Self {
        Self {
            error: error.into(),
            retryable: false,
        }
    }
}

/// Outcome of `TaskQueue::fail`.
///
/// `next_attempt_at` is informational (computed on the client clock); the
/// authoritative eligibility time is `available_at`, decided by the backend.
#[derive(Debug, Clone)]
pub enum FailOutcome {
    RetryScheduled {
        /// Attempt number of the upcoming retry.
        attempts: u32,
        next_attempt_at: OffsetDateTime,
    },
    DeadLettered {
        attempts: u32,
    },
}

/// Parameters for `TaskQueue::claim`.
#[derive(Debug, Clone)]
pub struct ClaimOptions {
    pub worker_id: WorkerId,
    /// Lease duration; must exceed worst-case handler runtime (or be renewed
    /// via `extend_lease` heartbeats).
    pub lease_duration: Duration,
    /// Maximum tasks to claim in one call (atomic batch).
    pub max_tasks: usize,
}

impl ClaimOptions {
    pub const fn new(worker_id: WorkerId, lease_duration: Duration) -> Self {
        Self {
            worker_id,
            lease_duration,
            max_tasks: 1,
        }
    }
}
